CREATE TABLE public.profiles (id uuid PRIMARY KEY, display_name text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY "own profile" ON public.profiles FOR ALL TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id); CREATE TYPE public.entry_kind AS ENUM ('despesa','receita'); CREATE TYPE public.entry_status AS ENUM ('pendente','pago'); CREATE TABLE public.categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL, kind public.entry_kind NOT NULL DEFAULT 'despesa', color text NOT NULL DEFAULT '#64748b', icon text NOT NULL DEFAULT 'Tag', created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX categories_user_idx ON public.categories(user_id); GRANT SELECT, INSERT, UPDATE, DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role; ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY; CREATE POLICY "own categories" ON public.categories FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); CREATE TABLE public.entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, description text NOT NULL, amount numeric(14,2) NOT NULL DEFAULT 0, due_date date NOT NULL, category_id uuid REFERENCES public.categories(id) ON DELETE SET NULL, kind public.entry_kind NOT NULL DEFAULT 'despesa', status public.entry_status NOT NULL DEFAULT 'pendente', paid_at date, notes text, attachment_path text, barcode text, series_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX entries_user_due_idx ON public.entries(user_id, due_date); GRANT SELECT, INSERT, UPDATE, DELETE ON public.entries TO authenticated; GRANT ALL ON public.entries TO service_role; ALTER TABLE public.entries ENABLE ROW LEVEL SECURITY; CREATE POLICY "own entries" ON public.entries FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); CREATE OR REPLACE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$; CREATE TRIGGER entries_touch BEFORE UPDATE ON public.entries FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER profiles_touch BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id, display_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'name', split_part(NEW.email,'@',1))) ON CONFLICT (id) DO NOTHING; INSERT INTO public.categories (user_id, name, kind, color, icon) VALUES (NEW.id,'Água','despesa','#38bdf8','Droplet'),(NEW.id,'Luz','despesa','#facc15','Zap'),(NEW.id,'Internet','despesa','#818cf8','Wifi'),(NEW.id,'Convênio','despesa','#f472b6','HeartPulse'),(NEW.id,'Hotel','despesa','#fb923c','BedDouble'),(NEW.id,'Prestação de carro','despesa','#22d3ee','Car'),(NEW.id,'IPVA','despesa','#f87171','ReceiptText'),(NEW.id,'IPTU','despesa','#a78bfa','Home'),(NEW.id,'Consórcio','despesa','#34d399','Landmark'),(NEW.id,'Mercado','despesa','#4ade80','ShoppingCart'),(NEW.id,'Empregada','despesa','#f0abfc','Sparkles'),(NEW.id,'Combustível','despesa','#fbbf24','Fuel'),(NEW.id,'Salário','receita','#22c55e','Wallet'),(NEW.id,'Outras receitas','receita','#14b8a6','TrendingUp'); RETURN NEW; END; $$; CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user(); CREATE POLICY "anexos own read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'anexos' AND auth.uid()::text = (storage.foldername(name))[1]); CREATE POLICY "anexos own insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'anexos' AND auth.uid()::text = (storage.foldername(name))[1]); CREATE POLICY "anexos own delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'anexos' AND auth.uid()::text = (storage.foldername(name))[1]);